class Solution:
    def circularArrayLoop(self, nums):
        n = len(nums)
        color = [0] * n
        for i in range(n):
            if color[i]:
                continue
            cur, cid = i, i + 1
            while True:
                nxt = (cur + nums[cur]) % n
                if nxt == cur or (nums[nxt] > 0) != (nums[i] > 0):
                    for j in range(n):
                        if color[j] == cid:
                            color[j] = -1
                    break
                if color[nxt] == cid:
                    return True
                if color[nxt] != 0:
                    for j in range(n):
                        if color[j] == cid:
                            color[j] = -1
                    break
                color[nxt] = cid
                cur = nxt
        return False

