class Solution:
    def circularArrayLoop(self, nums):
        n = len(nums)

        def nxt(i):
            return ((i + nums[i]) % n + n) % n

        visited = [False] * n
        for s in range(n):
            if visited[s]:
                continue
            slow, fast = s, s
            ok = True
            while True:
                slow = nxt(slow)
                fast = nxt(nxt(fast))
                if (nums[slow] > 0) != (nums[s] > 0) or slow == nxt(slow) or \
                   (nums[fast] > 0) != (nums[s] > 0) or fast == nxt(fast):
                    ok = False
                    break
                if slow == fast:
                    break
            # mark path visited
            cur = s
            while not visited[cur]:
                visited[cur] = True
                cur = nxt(cur)
            if ok and slow == fast:
                # verify cycle length > 1 and uniform direction
                cur = nxt(slow)
                length = 1
                good = True
                while cur != slow:
                    if cur == nxt(cur) or (nums[cur] > 0) != (nums[slow] > 0):
                        good = False
                        break
                    length += 1
                    cur = nxt(cur)
                if good and length > 1:
                    return True
        return False

